// Turn Log Row (main v194). From 29 Sep nobody's scripts read n8n's executions, so each turn leaves one row in the
// Jessie Log sheet's "Turn Log" tab. v193 failed on every turn ("Unknown error") - it looked nodes up by a variable name
// and read the AI Agent directly. Now: only literal node names on the main path, each in its own try; the tool calls come
// from Guard Probe's toolsLog. Never throws: a failure only means a missing log row.
const clip = (s, n) => { s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '...' : s; };
const row = { Time: '', Exec: '', User: '', Message: '', Path: '', Tools: '', Reply: '', Claim: '', Seconds: '', Build: '' };
try {
  row.Time = new Date().toLocaleString('en-CA', { timeZone: 'Asia/Manila', hour12: false }).replace(',', '');
  try { row.Exec = String($execution.id || ''); } catch (e) {}
  try { row.Build = String($workflow.name || ''); } catch (e) {}
  let t = {}; try { t = $('Slack Trigger').first().json || {}; } catch (e) {}
  row.User = String(t.user || '');
  try { row.User = ((($('Get Booker').first() || {}).json || {}).fields || {}).Name || row.User; } catch (e) {}
  row.Message = clip(t.text, 1000);
  const inp = ($input.first() || {}).json || {};
  let gp = null, bd = null, cd = null, ad = null, md = null;
  try { md = $('Move Direct').first().json || null; } catch (e) {}
  try { gp = $('Guard Probe').first().json || null; } catch (e) {}
  try { bd = $('Book Direct').first().json || null; } catch (e) {}
  try { cd = $('Cancel Direct').first().json || null; } catch (e) {}
  try { ad = $('Already Done Reply').first().json || null; } catch (e) {}
  let fo = null, mn = null;   // v263
  try { fo = $('Send Form Offer').first().json || null; } catch (e) {}
  try { mn = $('Send Menu').first().json || null; } catch (e) {}
  let cr = null; try { cr = $('Send Change Reply').first().json || null; } catch (e) {}   // v265
  try { if (!mn) mn = $('Send Late Menu').first().json || null; } catch (e) {}   // v267
  let mi = null; try { mi = $('Send Mine').first().json || null; } catch (e) {}   // v272
  let fa = null; try { fa = $('Send Facts').first().json || null; } catch (e) {}   // v286
  row.Path = inp._dup ? 'duplicate dropped' : bd ? 'book direct' : cd ? 'cancel direct' : md ? 'move direct' : ad ? 'already done' : fo ? 'form offer' : cr ? 'change offer' : mi ? 'my bookings' : fa ? 'room details' : mn ? 'menu' : 'agent';
  const res = r => r ? [r.status || r.verdict || '', r.reason || ''].filter(Boolean).join(' ') : '';
  row.Tools = bd ? 'Book Direct -> ' + res(bd) : cd ? 'Cancel Direct -> ' + res(cd) : md ? 'Move Direct -> ' + res(Array.isArray(md) ? md[0] : md) : clip((gp && gp.toolsLog) || '', 6000);
  row.Claim = String((gp && gp.claimProbe) || '');
  row.Reply = inp._dup ? '(nothing sent: a late copy of a message already answered)' : clip((inp.message && inp.message.text) || inp.text || '', 1500);
  const ts = parseFloat(String(t.ts || '0')) || 0;
  if (ts) row.Seconds = ((Date.now() / 1000) - ts).toFixed(1);
} catch (e) { row.Reply = row.Reply || ('(log error: ' + e.message + ')'); }
return [{ json: row }];

// Duplicate Check (main v189, PENDING 57). Slack sometimes fails a delivery and retries it a minute later; by then the
// requester has often re-sent the same text, which was answered. The late copy used to run as a new message (29 Sep
// 15:41 and 16:16 PHT: two identical summaries, then "That's already booked"). A message is dropped here when the same
// person sent the same text within 2 minutes, no Jessie message falls between the two, and Jessie has replied after
// both - that one was answered already. Passes Gate Context's output through untouched otherwise. Never throws.
let dup = false, why = '';
try {
  const trig = $('Slack Trigger').first().json || {};
  const norm = s => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();
  const me = String(trig.user || ''), myTs = parseFloat(String(trig.ts || '0')) || 0, mine = norm(trig.text);
  let msgs = []; try { msgs = $('Get Recent Messages').all().map(i => (i && i.json) || {}); } catch (e) {}
  const isBot = m => Boolean(m.bot_id || (m.message && m.message.bot_id)) || m.subtype === 'bot_message';
  const L = msgs.map(m => ({ ts: parseFloat(String(m.ts || '0')) || 0, bot: isBot(m), user: String(m.user || ''), t: norm(m.text || (m.message && m.message.text)) }))
    .filter(x => x.ts);
  if (me && myTs && mine) {
    for (const o of L) {
      if (o.bot || o.user !== me || o.t !== mine || o.ts === myTs || Math.abs(o.ts - myTs) > 120) continue;
      const lo = Math.min(o.ts, myTs), hi = Math.max(o.ts, myTs);
      const between = L.some(x => x.bot && x.ts > lo && x.ts < hi);
      const after = L.some(x => x.bot && x.ts > hi);
      if (!between && after) { dup = true; why = 'same text as the message at ' + o.ts + ', already answered'; break; }
    }
  }
} catch (e) { dup = false; }
if (dup) return [{ json: { _dup: true, _dupWhy: why } }];
return $input.all();

// Cancel Direct Reply (main v177): the requester's answer, from Cancel Booking's result - never its model-facing
// instructions. "Cancelled" only on CANCELLED.
// v187: read Cancel Direct by name - the input is now Prepare Next Cancel's result when a next card was queued.
const r = (() => { try { const j = $('Cancel Direct').first().json || {}; return Array.isArray(j) ? (j[0] || {}) : j; } catch (e) { return {}; } })();
const st = String(r.status || '').toUpperCase(), why = String(r.reason || '').toUpperCase();
const T = {
  NOT_ON_CALENDAR: "I can't find that booking any more - it may already have been cancelled. Nothing else was changed.",
  CHANGED: "That booking has changed since I showed it to you, so nothing was cancelled. Ask me again and I'll show you the current details.",
  NOT_YOURS: "That booking was made by someone else, and you don't have authority to cancel it. Nothing was cancelled.",
  NO_REFERENCE: "That booking has no booker on record, so I can't cancel it. Nothing was cancelled - please ask the studio team.",
  LOOKUP_FAILED: "I couldn't read the calendar just now, so nothing was cancelled. Please try again in a moment.",
};
let text;
if (st === 'CANCELLED') text = String(r.human || '').trim() || 'Cancelled.';
else if (T[why]) text = T[why];
else text = "I couldn't confirm that cancellation went through. Please check the calendar before trying again.";
// v187 (PENDING 55): more bookings were asked for in the same message - show the next card, with its own code and
// its own yes. Whatever is still queued after it rides along as "_Next: ..._" lines, so any number chain.
let nextShown = '';
try {
  const q = ((($('Prepared Cancel').first() || {}).json || {})._cancelDirect || {}).next || [];
  if (q.length) {
    let nx = {}; try { const j = $('Prepare Next Cancel').first().json || {}; nx = Array.isArray(j) ? (j[0] || {}) : j; } catch (e) {}
    const rest = q.slice(1).map(x => "_Next: " + x.title + " on " + x.date_text + " - I'll show it after this one._");
    if (String(nx.status || nx.verdict || '').toUpperCase() === 'PREPARED' && nx.card_text) {
      let card = String(nx.card_text);
      if (rest.length) card = /_check [0-9a-f]{8}_/.test(card) ? card.replace(/(_check [0-9a-f]{8}_)/, '$1\n' + rest.join('\n'))
        : card.replace(/\n*(?:Reply only with "yes" to cancel[^\n]*\n)?\s*Confirm to cancel\.\s*$/i, '\n' + rest.join('\n') + '\n\nConfirm to cancel.');   // v204
      card = card.replace(/\n*Reply only with "yes" to cancel\b[^\n]*\n\s*Confirm to cancel\.\s*$/i, '\n\nCancel it? Reply yes or no.')
                 .replace(/\n*Confirm to cancel\.\s*$/i, '\n\nCancel it? Reply yes or no.');
      text += '\n\nNext:\n\n' + card.trim();
      nextShown = q[0].title;
    } else {
      text += '\n\nI couldn\'t get "' + q[0].title + '" (' + q[0].date_text + ') ready to cancel, so it is untouched.'
        + (q.length > 1 ? ' Still to do: ' + q.slice(1).map(x => '"' + x.title + '"').join(', ') + '.' : '')
        + ' Ask me again for ' + (q.length > 1 ? 'them' : 'it') + '.';
    }
  }
} catch (e) {}
return [{ json: { output: text, directCancel: { status: st, reason: why, nextShown } } }];

// Prepared Cancel (main v177). A yes to a cancel card that Cancel Booking wrote (prepare mode) is carried out in
// code - Cancel Direct - without the model: 28 Sep QA, the model wrote cancel cards itself (once with an invented
// room and time), called Cancel Booking before showing the booking, and a Gemini 503 on the yes left a booking
// uncancelled. Reads the newest Jessie message (the card the yes answers); needs the gate's confirmedCancel, the
// card's check code, and a card under 4 hours old. Anything else -> the model handles the turn as before.
// Passes its input through, so the agent sees what it always did.
let d = { use: false, reason: '' };
try {
  const gate = ($('Gate Context').first() || {}).json || {};
  let msgs = []; try { msgs = $('Get Recent Messages').all().map(i => (i && i.json) || {}); } catch (e) {}
  const isBot = m => Boolean(m.bot_id || (m.message && m.message.bot_id)) || m.subtype === 'bot_message';
  const bot = msgs.find(isBot);
  // Slack escapes &, < and > in message text; the title must match the calendar exactly.
  const t = bot ? String(bot.text || (bot.message && bot.message.text) || '').replace(/\r/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim() : '';
  const code = (t.match(/_check ([0-9a-f]{8})_/) || [])[1];
  const lines = t.split('\n').map(l => l.trim());
  const title = ((lines.find(l => /^\*[^*\n]+\*$/.test(l) && !/:\*/.test(l)) || '').replace(/^\*|\*$/g, '')).trim();
  const dl = ((lines.find(l => /^\*Date:\*/i.test(l)) || '').replace(/^\*Date:\*\s*/i, '')).trim();
  // v204: the short card prints no code - its Time and Room lines are what the yes must still match (Cancel Booking v21)
  const tl = ((lines.find(l => /^\*Time:\*/i.test(l)) || '').replace(/^\*Time:\*\s*/i, '')).trim();
  const rl = ((lines.find(l => /^\*Room:\*/i.test(l)) || '').replace(/^\*Room:\*\s*/i, '')).trim();
  // v204: a card without a code counts only in exactly Cancel Booking v21's shape - title, Date, Time, Room, Booked by,
  // queued _Next: lines, the confirmation. Anything else (a card the model wrote) -> the model handles it, as before.
  const ti = lines.findIndex(l => /^\*[^*\n]+\*$/.test(l) && !/:\*/.test(l));
  const shortShape = ti >= 0 && lines.slice(ti + 1).every(l => !l || /^\*(Date|Time|Room|Booked by):\*/.test(l) || /^_Next: .+_$/.test(l) || /^_Also named .+_$/.test(l) || /^Heads up: this booking has already passed\.$/.test(l)   // v221: Cancel Booking v22's past note and the other bookings with that name
    || /^(Confirm to cancel\.(\s*\(yes\/no\))?|Cancel it\? Reply yes or no\.)$/i.test(l));
  const M = ['january','february','march','april','may','june','july','august','september','october','november','december'];
  const dm = dl.match(/([A-Za-z]+)\s+(\d{1,2}),\s*(\d{4})/); const mo = dm ? M.indexOf(dm[1].toLowerCase()) : -1;
  const ymd = mo >= 0 ? dm[3] + '-' + String(mo + 1).padStart(2, '0') + '-' + String(+dm[2]).padStart(2, '0') : '';
  const ageH = bot && bot.ts ? (Date.now() / 1000 - parseFloat(bot.ts)) / 3600 : 99;
  if (gate.confirmedCancel !== true) d.reason = 'not a confirmed cancel';
  else if (!/(?:Confirm to cancel\.\s*(?:\(yes\/no\)\s*)?|Cancel it\? Reply yes or no\.\s*)$/i.test(t)) d.reason = 'the last message is not a cancel card';
  else if (!code && !(tl && rl && shortShape)) d.reason = 'the card has no check code and is not the short card Cancel Booking writes';
  else if (!title || !ymd) d.reason = 'the card has no title or date';
  else if (ageH > 4) d.reason = 'the card is more than 4 hours old';
  else {
    // v187 (PENDING 55): the other bookings asked for in the same message, queued on the card by Guard Probe.
    const next = lines.map(l => l.match(/^_Next: (.+) on (?:[A-Za-z]+day, )?([A-Za-z]+)\s+(\d{1,2}),\s*(\d{4}) - I'll show it after this one\._$/))
      .filter(Boolean).map(m => { const k = M.indexOf(m[2].toLowerCase());
        return { title: m[1].trim(), date_text: m[0].replace(/^_Next: .+ on /, '').replace(/ - I'll show.*$/, ''), booking_date: k >= 0 ? m[4] + '-' + String(k + 1).padStart(2, '0') + '-' + String(+m[3]).padStart(2, '0') : '' }; })
      .filter(x => x.title && x.booking_date);
    d = { use: true, reason: '', title, booking_date: ymd, check_code: code || '', card_time: code ? '' : tl, card_room: code ? '' : rl, next };
  }
  // The model's own Cancel Booking call (when the direct path declines) is held to the card too.
  if (/(?:Confirm to cancel\.\s*(?:\(yes\/no\)\s*)?|Cancel it\? Reply yes or no\.\s*)$/i.test(t) && code) d.card_code = code;
  if (/(?:Confirm to cancel\.\s*(?:\(yes\/no\)\s*)?|Cancel it\? Reply yes or no\.\s*)$/i.test(t) && !code && tl && rl && shortShape) { d.card_time = tl; d.card_room = rl; }   // v204
} catch (e) { d = { use: false, reason: 'error: ' + e.message }; }
// 29 Sep (QA bug 17): a second bare "yes" after Jessie already reported the result went to the model, which retried
// and replied that the room was taken - by the requester's own booking. Answered here instead.
let done = '';
try {
  const g2 = ((($('Gate Context').first() || {}).json || {}).gate) || {};
  let ms = []; try { ms = $('Get Recent Messages').all().map(i => (i && i.json) || {}); } catch (e) {}
  const b = ms.find(m => Boolean(m.bot_id || (m.message && m.message.bot_id)) || m.subtype === 'bot_message');
  const bt = b ? String(b.text || (b.message && b.message.text) || '').trim() : '';
  // v201: a message that ends in a card waiting for a yes is not a finished action - since v198 a series move sends
  // 'Moved ...' with the next date's card, and its yes was answered "That's already moved" (30 Sep 17:07).
  const _waits = /(?:(?:Book|Cancel|Move) it\? Reply yes or no\.|Confirm to (?:book|cancel|move)\.(?:\s*\((?:y\/n|yes\/no)\))?)\s*$/i.test(bt);
  // v245 (8 Oct 20:23): "cancel it" is in Gate Context's YES list (a reply to a cancel card), so "cancel it" right after
  // "Moved ..." was answered "That's already moved". A yes that names an action only repeats that same action.
  const _sd = String(g2.said || '').toLowerCase();
  const _verb = /\bcancel it\b/.test(_sd) ? 'cancel' : /\bbook it\b/.test(_sd) ? 'book' : '';
  if (g2.saidYes === true && !d.use && !_waits) {
    if (/^Booked\b/.test(bt) && (!_verb || _verb === 'book')) done = "That's already booked - nothing else was changed.";
    else if (/^Cancelled\b/.test(bt) && (!_verb || _verb === 'cancel')) done = "That's already cancelled - nothing else was changed.";
    else if (/^Moved\b/.test(bt) && !_verb) done = "That's already moved - nothing else was changed.";
  }
  // v247 (brevity): a "no" to a card is answered here, in code - the model wrote "Understood, the booking won't go ahead.
  // Nothing was created. What would you like changed on the QATEST2 session, or should I leave it there?"
  if (g2.saidNo === true && !d.use && _waits) {
    if (/Cancel it\? Reply yes or no\.\s*$|Confirm to cancel\./i.test(bt)) done = 'Okay - it stays booked.';
    else if (/Move it\? Reply yes or no\.\s*$|Confirm to move\./i.test(bt)) done = 'Okay - it stays where it is.';
    else done = 'No problem - nothing was booked. What would you like to change?';
  }
} catch (e) { done = ''; }
return [{ json: Object.assign({}, $input.first().json || {}, { _cancelDirect: d, _alreadyDone: done }) }];

// Reference Lookup Failed (main v173): the cache was unusable and the refresh failed, so there is no trustworthy
// room / session type / staff list. Say so plainly rather than let the model answer without it.
const why = String(($input.first().json || {}).reason || '');
return [{ json: {
  output: "I couldn't load the room and staff lists just now, so I can't check or book anything yet. Please try again in a few minutes.",
  referenceLookup: { ok: false, reason: why },
} }];

// Reference Snapshot (main v173): the one validated copy of rooms, session types and bookers this turn uses.
// Fresh cache -> the row from Read Reference Cache. Otherwise -> the row Refresh Cache Now just wrote.

const REQUIRED = { rooms: 'Room Name', sessionTypes: 'Type', bookers: 'Name' };
function readRow(row) {
  if (!row || row.error || row.cache_key !== 'jessie-reference') return { ok: false, reason: 'no cache row' };
  const at = Date.parse(row.refreshed_at || '');
  if (isNaN(at)) return { ok: false, reason: 'refreshed_at missing or not a date' };
  let data;
  try { data = JSON.parse(row.payload); } catch (e) { return { ok: false, reason: 'payload is not JSON' }; }
  if (!data || typeof data !== 'object') return { ok: false, reason: 'payload is not an object' };
  for (const [k, f] of Object.entries(REQUIRED)) {
    const a = data[k];
    if (!Array.isArray(a) || !a.length) return { ok: false, reason: k + ' missing or empty' };
    for (const r of a) {
      if (!r || typeof r.id !== 'string' || !r.fields || typeof r.fields !== 'object' || !String(r.fields[f] || '').trim())
        return { ok: false, reason: k + ' has a malformed record' };
    }
  }
  return { ok: true, at, refreshed_at: row.refreshed_at, data };
}
// Upsert is not relied on to keep the key unique: with duplicate keyed rows, the newest valid one wins.
function newest(rows) {
  let best = null, why = 'no cache row';
  for (const r of rows) {
    const v = readRow(r);
    if (!v.ok) { if (r && r.cache_key) why = v.reason; continue; }
    if (!best || v.at > best.at) best = v;
  }
  return best || { ok: false, reason: why };
}

const inp = $input.first().json || {};
let rows, source;
if (Object.prototype.hasOwnProperty.call(inp, 'cacheFresh')) {
  source = 'cache';
  rows = $('Read Reference Cache').all().map(i => i.json || {});
} else {
  source = 'refresh';
  rows = $input.all().map(i => i.json || {});
}
const c = newest(rows);
if (!c.ok) {
  const err = inp.error ? ('refresh failed: ' + (inp.error.message || inp.error)) : c.reason;
  return [{ json: { ok: false, source, reason: String(err).slice(0, 300) } }];
}
return [{ json: { ok: true, source, refreshed_at: c.refreshed_at,
  rooms: c.data.rooms, sessionTypes: c.data.sessionTypes, bookers: c.data.bookers } }];

// Check Reference Cache (main v173): is the cached reference data usable and at most 15 minutes old?
// Reads every row the key matched (normally one). Emits one small item; the payload stays in Read Reference Cache.

const REQUIRED = { rooms: 'Room Name', sessionTypes: 'Type', bookers: 'Name' };
function readRow(row) {
  if (!row || row.error || row.cache_key !== 'jessie-reference') return { ok: false, reason: 'no cache row' };
  const at = Date.parse(row.refreshed_at || '');
  if (isNaN(at)) return { ok: false, reason: 'refreshed_at missing or not a date' };
  let data;
  try { data = JSON.parse(row.payload); } catch (e) { return { ok: false, reason: 'payload is not JSON' }; }
  if (!data || typeof data !== 'object') return { ok: false, reason: 'payload is not an object' };
  for (const [k, f] of Object.entries(REQUIRED)) {
    const a = data[k];
    if (!Array.isArray(a) || !a.length) return { ok: false, reason: k + ' missing or empty' };
    for (const r of a) {
      if (!r || typeof r.id !== 'string' || !r.fields || typeof r.fields !== 'object' || !String(r.fields[f] || '').trim())
        return { ok: false, reason: k + ' has a malformed record' };
    }
  }
  return { ok: true, at, refreshed_at: row.refreshed_at, data };
}
// Upsert is not relied on to keep the key unique: with duplicate keyed rows, the newest valid one wins.
function newest(rows) {
  let best = null, why = 'no cache row';
  for (const r of rows) {
    const v = readRow(r);
    if (!v.ok) { if (r && r.cache_key) why = v.reason; continue; }
    if (!best || v.at > best.at) best = v;
  }
  return best || { ok: false, reason: why };
}

const MAX_AGE_MS = 15 * 60 * 1000;
const c = newest($input.all().map(i => i.json || {}));
const age = c.ok ? Date.now() - c.at : null;
const fresh = c.ok && age <= MAX_AGE_MS && age >= -2 * 60 * 1000;   // a clock skew of 2 min is tolerated
return [{ json: {
  cacheFresh: fresh,
  cacheState: !c.ok ? c.reason : (fresh ? 'fresh' : 'stale'),
  cacheRefreshedAt: c.ok ? c.refreshed_at : '',
  cacheAgeSec: c.ok ? Math.round(age / 1000) : null,
} }];

// Book Direct Reply (v169). A verified "yes" to a prepared summary is booked in code, without the model:
// 28 Sep QA, on v168, the model answered two of four such yeses by calling Prepare Booking again - once
// nothing was booked, once it booked and the reply was a fresh "Confirm to book." summary. Book Session's own
// human text is relayed as is: "Booked." or the refusal and what to do about it.
let r = {};
try { r = $input.first().json || {}; if (Array.isArray(r)) r = r[0] || {}; } catch (e) {}
let text = String(r.human || '').trim();
// v210 (live 2 Oct 01:50): Book Session's refusal text is written for the model ("Ask the requester who the client is ...
// present the summary again") and this reply skips Guard Probe - drop every sentence meant for the model.
if (text && String(r.status || '').toUpperCase() !== 'CREATED') {
  const _MODEL = /\b(?:the requester|requester's|ask (?:them|the)|call (?:prepare|book|move|cancel)|prepare (?:it|booking)|present the summary|pass (?:client|booked_for|room)|leave (?:it|the client|booked_for) empty|room_override|tool|exactly as they type|must not (?:be|appear)|check the times with)\b/i;
  const _kept = text.split(/(?<=[.!?])\s+/).filter(x => x && !_MODEL.test(x));
  text = _kept.join(' ').trim();
  if (!text || /^Nothing was (?:booked|prepared)\.?$/i.test(text)) text = 'Nothing was booked - something changed since that card. Send the booking again and I’ll check it.';
}
if (!text) text = (String(r.status || '').toUpperCase() === 'CREATED')
  ? 'Booked.'
  : "I couldn't confirm that booking went through. Please check the calendar before booking it again.";
return [{ json: { output: text, directBooking: { status: r.status || r.verdict || '', reason: r.reason || '', event_id: r.event_id || '' } } }];

// v163 Prepare Booking (Howard, 2026-09-28 - option 2 of the eval report). At the yes, the booking is the summary
// the requester approved, not whatever the model sends. That summary was rendered by Book Session in prepare mode
// with a check code over its booking lines; this reads that exact Slack message back (the newest bot message, the
// one the yes answers), re-checks the code, and turns it into Book Session's inputs. The Book Session tool uses
// these instead of the model's values whenever `use` is true, and refuses a studio booking (NOT_PREPARED) when a
// yes answers a summary that did not come from Prepare Booking or was altered. Never throws: on any error `use`
// is false and Book Session refuses rather than guessing.
// --- Prepared booking summary: shared by Book Session "Render Summary" and main "Prepared Booking" (v51/v163) ---
// The summary a requester approves is the booking. Code renders it in one fixed format and ends it with a short
// check code over the booking lines; at the yes, main reads that exact message back, re-checks the code, and hands
// those details to Book Session. Keep PB_FIELDS, pbNorm and pbCode identical in both nodes.
const PB_SALT = '4539361661025d1d';
const PB_FIELDS = ['Title', 'Client', 'Project', 'Session Type', 'Date', 'Time', 'Room', 'Engineer', 'Arranger', 'Department', 'Booking Type', 'Booked by', 'Override'];
