  // v212 (live 2 Oct 12:29, PENDING 77): the time too - "And which day and time?" / "And which day?" / "And what time?"
  const _noTime = !/\b\d{1,2}(?::\d{2})?\s*(?:am|pm|a\.m\.|p\.m\.|nn|noon)\b|\b\d{1,2}:\d{2}\b|\b(?:noon|midnight|morning|afternoon|evening|tonight|lunch|all day|whole day|half day)\b|\bat\s+\d{1,2}\b|\b\d{1,2}\s*(?:-|\u2013|to|until|till)\s*\d{1,2}\b/i.test(_rt)
    && !/\bM[1-8]\b/i.test(_rt);
  const _askDay = _noDate && !/\b(date|day|when)\b/i.test(text), _askTime = _noTime && !/\b(time|when|hours?)\b/i.test(text);
  // v214 (live 2 Oct 13:02): the project too, when the requester named none ("project ...", or a name in capitals)
  const _bfp = String(((($('Booked For').first() || {}).json) || {}).project || '').trim();
  const _askProj = !_bfp && !/\b(project|title)\b/i.test(text) && !/\bproject\b/i.test(_rt) && !/\b(?!AM\b|PM\b|VO\b|ISR\b|QC\b|HL\b)[A-Z][A-Z0-9&-]{2,}\b/.test(_rt.replace(/\bStudio\s+[A-Z0-9]\b|\bM[1-8]\b/g, '')) && /\b(?:studio|booth)\b/i.test(_rt);
  // v218 (live 6 Oct 13:32): the client too, when none was named or declined - asked with the first questions
  const _bfc = (($('Booked For').first() || {}).json) || {};
  const _askCli = !String(_bfc.client || _bfc.forClient || '').trim() && !/\bclients?\b/i.test(text) && !/\bclients?\b|\bprodu(?:cer)?\b|\b(?:none|nope|nah|wala|n\/?a|nobody|no one|not applicable)\b/i.test(_rt)
    && !/\b(?:personal|my own|own project|internal|meeting|event)\b/i.test(_rt) && /\b(?:studio\s+[a-z0-9]|booth)\b/i.test(_rt);
