text = text.replace(/<(?:you|them|name|colleague|client|another client|client a|client b|room|free room|session type|title|owner|meeting title|event|project|ei|ddd|d|month d|month d, yyyy)>/gi, '')
           .replace(/\[(?:Full Name|Role)\]/g, '').replace(/[ \t]{2,}/g, ' ');

