//    Only the general free list (free_rooms, no session type, no single room asked about), never a summary.
try {
  if (!_prepared && steps && !/Confirm to (book|cancel|move)\./i.test(text)) {
    let _free = null;
    for (let i = steps.length - 1; i >= 0; i--) {
      const _t = String(((steps[i] || {}).action || {}).tool || '').replace(/[_\s]+/g, ' ').toLowerCase();
      if (_t !== 'room availability') continue;
      let _o = null; try { _o = [].concat(JSON.parse(String((steps[i] || {}).observation || '')))[0]; } catch (e) {}
      if (_o && _o.status === 'OK' && !_o.asked && Array.isArray(_o.free_rooms)) _free = _o.free_rooms.map(String);
