      if (/\b(?:kind|type) of session\b|\bsession type\b/i.test(text)) _it.push('session type');
      if (/\bproject\b/i.test(text)) _it.push('project');
      if (/\bclient\b/i.test(text)) _it.push('client');
      if (/\bengineer\b/i.test(text)) _it.push('engineer');
      // v249: the fixed shape itself ("What's the date, time, ...", v247's own words, or the model copying them) is read too
      if (/\bthe date\b|\bdate(?:,| and)/i.test(text)) _it.push('date');
      if (/\bthe time\b|\b(?:date|day)(?:,| and) time\b|\btime(?:,| and) /i.test(text)) _it.push('time');
      if (/\blength\b|\bduration\b/i.test(text)) _it.push('length');
      { const _O = ['date', 'time', 'length', 'room', 'session type', 'project', 'client', 'engineer'];
        const _u = [...new Set(_it)].sort((a, b) => _O.indexOf(a) - _O.indexOf(b)); _it.length = 0; _u.forEach(x => _it.push(x)); }
      // v249 (PENDING 105): never "time" and "length" together - a time range gives the length
      if (_it.indexOf('time') !== -1 && _it.indexOf('length') !== -1) _it.splice(_it.indexOf('length'), 1);
      // v250 (live 9 Oct 11:39): a details question asking the session type, with no project known, asks for the project too
      try { const _bp = (($('Booked For').first() || {}).json) || {};
        if (_it.length >= 2 && _it.indexOf('session type') !== -1 && _it.indexOf('project') === -1 && !String(_bp.project || _bp.projectCode || '').trim())
          _it.splice(_it.indexOf('session type') + 1, 0, 'project'); } catch (e) {}
      // v251 (live 9 Oct 11:49): an engineer Booked For knows (named, or the requester as the default) is not asked
      try { const _be = (($('Booked For').first() || {}).json) || {}; if (_be.engineerResolved && String(_be.engineer || '').trim() && _it.indexOf('engineer') !== -1) _it.splice(_it.indexOf('engineer'), 1); } catch (e) {}
      // v249 (PENDING 103): what is already known is said back first - the room (Early Room Plan), the date (Gate Context)
      // and the time (Booked For), each from the requester's own words - and not asked again
      const _kn = { room: '', date: '', time: '' };
      if (_it.length >= 2) {
        try { _kn.room = String(((($('Early Room Plan').first() || {}).json || {}).earlyPlan || {}).knownRoom || ''); } catch (e) {}
        try { const _ds = String((($('Gate Context').first() || {}).json || {}).datesUnderDiscussion || '').split(',').map(x => x.trim()).filter(x => /^\d{4}-\d{2}-\d{2}$/.test(x));
          // the date only when the model did not ask for it, or it was named in this message - a date carried from earlier
          // today may belong to another booking
          const _dm = String((($('Gate Context').first() || {}).json || {}).datesInMessage || '').split(',').map(x => x.trim()).filter(Boolean);
          if (_ds.length === 1 && (_it.indexOf('date') === -1 || _dm.indexOf(_ds[0]) !== -1)) _kn.date = new Date(_ds[0] + 'T12:00:00+08:00').toLocaleDateString('en-US', { timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric' }); } catch (e) {}
        try { const _bk = (($('Booked For').first() || {}).json) || {}, _f12 = x => (+x.slice(0, 2) % 12 || 12) + ':' + x.slice(3) + ' ' + (+x.slice(0, 2) < 12 ? 'AM' : 'PM');
          if (/^\d{2}:\d{2}$/.test(String(_bk.timeStart || '')) && /^\d{2}:\d{2}$/.test(String(_bk.timeEnd || ''))) _kn.time = _f12(_bk.timeStart) + ' – ' + _f12(_bk.timeEnd); } catch (e) {}
      }
      let _left = _it.filter(x => !((x === 'room' && _kn.room) || (x === 'date' && _kn.date) || ((x === 'time' || x === 'length') && _kn.time)));
      // v252 (decided 9 Oct): the date and time are settled first - while either is unknown only they are asked, and the
      // booking is said back (room · date · time) in the message that asks for the rest
      const _dtq = _left.filter(x => x === 'date' || x === 'time');
      if (_it.length >= 2 && _dtq.length) {
        text = (_freeSaid ? '✅ ' + _freeSaid + ' is free' + (_kn.date ? ' on ' + _kn.date : '') + '\n' : '')
          + (_dtq.length === 2 ? 'What date and time work?' : _dtq[0] === 'date' ? 'What date works?' : 'What time works?');
        _freeSaid = '';
      } else if (_it.length >= 2 && _left.length) {
        const _j = _left.length === 1 ? _left[0] : _left.length === 2 ? _left.join(' and ') : _left.slice(0, -1).join(', ') + ' and ' + _left[_left.length - 1];
        const _pre = _kn.time ? [_kn.room, _kn.date, _kn.time].filter(Boolean).join(' · ') : '';   // v255 (108): one form
        if (_pre) _freeSaid = '';   // the 🗓️ line says it
        text = (_pre ? '🗓️ ' + _pre + '\n\n' : '') + "What's the " + _j + '?' + (_left.indexOf('client') !== -1 ? ' (or "none" for no client)' : '');
      }
    }
    if (_freeSaid && !/^✅/.test(text)) text = '✅ ' + _freeSaid + ' is free\n' + text;   // v249: not rewritten - still said by code
  }
} catch (e) {}
// --- v258 (decided 9 Oct): booking questions written in code ----------------------------------------------------------
// The model asked for details in a new way each time patches closed one (v255-v257). On a studio booking, a reply that asks
// for booking details is replaced by code's question, from what Gate Context, Booked For and Early Room Plan already hold.
let bookingQ = '';
try {
  const _bk = (($('Booked For').first() || {}).json) || {};
  const _rt = String(_bk.requesterText || '');
  const _pl = (((($('Early Room Plan').first() || {}).json) || {}).earlyPlan) || {};
  const _gc = (($('Gate Context').first() || {}).json) || {};
  // judged on the model's own reply: a question code already wrote (a card turned into a question, a relay) is not replaced
  const _raw = String((($input.first() || {}).json || {}).output || '');
  const _askDet = /\?\s*$/.test(text) && /\?/.test(_raw) && /\b(?:session|project|client|time|date|day|engineer|kind of|type of|details?)\b/i.test(_raw);
  const _internal = /\b(?:m[\s-]?booth|m[1-8]|salin|likha|katha|lobby|conference)\b/i.test(_rt + ' ' + String(_pl.knownRoom || ''));
  const _series = /\b(?:every|weekly|daily|biweekly|fortnightly|recurring|series|weekdays)\b/i.test(_rt);
  const _cm = /^(?:a yes|answering a cancel or move card|a cancel or move)$/.test(String(_pl.why || '')) || /\b(?:cancel|move|resched\w*)\b/i.test(_rt);
  const _card = /\*Date:\*|\*Dates|\*Moving to:\*|\*Now:\*|\*Client:\*|\*Session Type:\*|Book it\?|Cancel it\?|Move it\?|Confirm to|_check [0-9a-f]{8}_/i.test(text + '\n' + _raw);
  if (_askDet && !_prepared && !_codeCard && !_card && !_internal && !_series && !_cm && /\b(?:book|reserve|schedule)\b/i.test(_rt) && !/^\s*(?:❌|✅|🗓️|⚠️)/.test(text)) {
    const _ds = String(_gc.datesUnderDiscussion || '').split(',').map(x => x.trim()).filter(x => /^\d{4}-\d{2}-\d{2}$/.test(x));
    const _date = _ds.length === 1 ? new Date(_ds[0] + 'T12:00:00+08:00').toLocaleDateString('en-US', { timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric' }) : '';
    const _f12 = x => (+x.slice(0, 2) % 12 || 12) + ':' + x.slice(3) + ' ' + (+x.slice(0, 2) < 12 ? 'AM' : 'PM');
    const _time = /^\d{2}:\d{2}$/.test(String(_bk.timeStart || '')) && /^\d{2}:\d{2}$/.test(String(_bk.timeEnd || '')) ? _f12(_bk.timeStart) + ' – ' + _f12(_bk.timeEnd) : '';
    if (!_date || !_time) {
      bookingQ = !_date && !_time ? 'What date and time work?' : !_date ? 'What date works?' : 'What time works?';
    } else {
      let _types = []; try { _types = [...new Set((JSON.parse(String((($('Room Table').first() || {}).json || {}).referenceData || '{}')).types || []).map(t => String(t.type || '').trim()).filter(Boolean))]; } catch (e) {}
      const _low = _rt.toLowerCase();
      const _named = _types.filter(t => _low.indexOf(t.toLowerCase()) !== -1);
      let _kind = '', _stMissing = false;
      if (!_named.length && _types.length) {
        const _g = ['mixing', 'recording', 'editing', 'dubbing'].find(w => new RegExp('\\b' + w + '\\b').test(_low));
        if (_g) { const _op = _types.filter(t => new RegExp('\\b' + _g + '\\b', 'i').test(t));
          const _nar = _op.filter(o => o.toLowerCase().split(/\s+/).filter(w => w !== _g).some(w => new RegExp('\\b' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b').test(_low)));
          if (_op.length >= 2 && _nar.length !== 1) _kind = 'Which kind of ' + _g + ' - ' + (_op.length === 2 ? _op.join(' or ') : _op.slice(0, -1).join(', ') + ' or ' + _op[_op.length - 1]) + '?'; }
        // nothing that names a session: asked only when the model asked too (shorthands like "isr" are read by Book Session)
        else _stMissing = /\b(?:kind|type) of session\b|\bsession type\b|\bwhat kind\b/i.test(text);
      }
      const _need = [];
      if (_stMissing) _need.push('session type');
      if (!String(_bk.project || _bk.projectCode || '').trim()) _need.push('project');
      const _noCl = String(_bk.clientAnswer || '') === 'none' || /\b(?:no|without(?: a| any)?|walang)\s+(?:a\s+)?clients?\b|\bclient\s*(?:is|:)?\s*(?:none|n\/?a|wala)\b/i.test(_rt);
      if (!String(_bk.client || _bk.forClient || '').trim() && !_noCl) _need.push('client');
      if (!_bk.engineerResolved && !String(_bk.engineer || '').trim() && /\bengineer\b/i.test(text)) _need.push('engineer');
      const _line = '🗓️ ' + [String(_pl.knownRoom || ''), _date, _time].filter(Boolean).join(' · ');
      if (_kind) bookingQ = _line + '\n\n' + _kind;
      else if (_need.length) bookingQ = _line + '\n\n' + (_need.length === 1
        ? ({ 'session type': "What's the session type?", project: "What's the project?", client: 'Who’s the client? (or "none")', engineer: 'Who’s the engineer?' })[_need[0]]
        : "What's the " + (_need.length === 2 ? _need.join(' and ') : _need.slice(0, -1).join(', ') + ' and ' + _need[_need.length - 1]) + '?' + (_need.indexOf('client') !== -1 ? ' (or "none" for no client)' : ''));
    }
    if (bookingQ) text = bookingQ;
  }
} catch (e) { bookingQ = ''; }

// v250: the early room check's part-day heads-up goes on top of the shortened reply
if (_erPre) text = _erPre + (String(text || '').trim() ? '\n\n' + text : '');

// --- v238 (card guard): a card no tool made never goes out -------------------------------------------------------------
// Slack round on Claude Haiku, 8 Oct 14:43 (main v237): "cancel QATEST on december 14 2027" got a cancel card the model
// wrote itself - no tool called, copied from earlier cards, showing the time from before a move one step earlier. Every real
// card comes from a tool (_prepared) or from the series-change code above (_codeCard). A reply ending in a confirmation line
// that neither made is withdrawn; the system message then tells the model which tool makes each card. Judged only when
// intermediateSteps is on the input (always, live), like the claim check.
let cardProbe = 'no card';
try {
  const _stC = ($input.first().json || {}).intermediateSteps;
  const _mk = text.match(/(?:\b(Book|Cancel|Move) it\? Reply yes or no\.|Confirm to (book|cancel|move)\.(?:\s*\((?:y\/n|yes\/no)\))?)\s*$/i);
  if (_mk) {
    if (_prepared || _codeCard) cardProbe = 'card from ' + (_prepared ? 'a tool' : 'code');
    else if (Array.isArray(_stC)) {
      const _v = String(_mk[1] || _mk[2]).toLowerCase();
      text = "Sorry, I couldn't check that against the calendar just now, so nothing was " + ({ book: 'booked', cancel: 'cancelled', move: 'moved' })[_v] + '. Could you send that again?';
      cardProbe = 'WITHDRAWN: a ' + _v + ' card no tool made';
    } else cardProbe = 'card, no intermediateSteps on input';
  }
} catch (e) {}

// --- v242 (memory notes, PENDING 99): what this turn leaves in the conversation memory -------------------------------
// n8n's memory keeps the text of each turn and no tool calls, so a card in it reads as a reply Jessie wrote herself, and
// Claude copied it (8 Oct). After the reply, `Note Card` puts this note in place of the turn's raw reply. Empty = no change.
// A reply that is only such a note, with no tool behind it, is withdrawn like a card (v238).
let memoryNote = '';
try {
  // v243 (transcript): also a reply that is only a bracketed line ("[Availability check run by its tool ...]", 8 Oct
  // 19:49 on v242) or written in the transcript's format ("Jessie showed ...", "Requester: ...").
  const _noteOnly = /^\s*\[(?:(?:book|booking|cancel|move|series) card shown|Nothing was done:)/i.test(text)
    || /^\s*\[[^\]\n]{8,}\]\s*$/.test(text) || /^\s*(?:Jessie (?:showed|said)\b|Requester:)/.test(text);
  if (_noteOnly && !_prepared && !_codeCard && Array.isArray(($input.first().json || {}).intermediateSteps)) {
    text = "Sorry, I couldn't check that against the calendar just now, so nothing was changed. Could you send that again?";
    cardProbe = 'WITHDRAWN: a memory note no tool made';
  }
  const _flat = s => String(s).split('\n').map(l => l.replace(/[*_]/g, '').trim())
    .filter(l => l && !/Reply yes or no\.|^Reply only with|^Confirm to (?:book|cancel|move)\./i.test(l) && !/^check [0-9a-f]{8}$/i.test(l))
    .join(' | ').slice(0, 400);
  const _kind = (text.match(/\b(Book|Cancel|Move) it\? Reply yes or no\.\s*$|Confirm to (book|cancel|move)\.\s*$/i) || []).slice(1).filter(Boolean)[0];
  if (/^card from/.test(cardProbe) && _kind) {
    const _k = /\*Dates(?: \(\d+\))?:\*/.test(text) ? 'Series' : _kind.charAt(0).toUpperCase() + _kind.slice(1).toLowerCase();
    memoryNote = '[' + _k + ' card shown, made by its tool: ' + _flat(text) + '. Waiting for their yes or no. A new, repeated or changed request needs the tool again.]';
  } else if (/^WITHDRAWN/.test(cardProbe)) {
    memoryNote = '[Nothing was done: a card no tool made was withdrawn. For this request, call the tool that makes the card.]';
  } else if (/NOT FOUND$/.test(claimProbe)) {
    memoryNote = '[Nothing was done: a "' + claimProbe.replace(/: NOT FOUND$/, '') + '" claim had no tool behind it and was withdrawn.]';
  }
} catch (e) {}

// v194: a compact list of this turn's tool calls, for the Turn Log (Turn Log Row cannot read the agent itself).
let toolsLog = '';
try {
  const _cl = (s, n) => { s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '...' : s; };
  const _K = ['title', 'booking_date', 'start', 'end', 'new_start', 'new_end', 'rooms', 'window_start', 'window_end', 'window_room', 'engineer', 'client', 'summary', 'recur_frequency', 'recur_days', 'recur_start', 'recur_count', 'recur_until', 'recur_time_start', 'recur_time_end'];   // v206: series inputs too
  toolsLog = _cl(((($input.first().json || {}).intermediateSteps) || []).map(s => {
    const a = (s && s.action) || {}, ti = a.toolInput || {};
    let o = null; try { o = [].concat(JSON.parse(String(s.observation || '')))[0]; } catch (e) {}
    return (a.tool || '?') + '(' + _K.filter(k => ti[k] !== undefined && ti[k] !== '').map(k => k + '=' + _cl(ti[k], 60)).join(', ') + ') -> '
      + (o ? [o.status || o.verdict || '', o.reason || ''].filter(Boolean).join(' ') : _cl(s.observation, 60));
  }).join(' | '), 6000);
} catch (e) { toolsLog = '(tools log error: ' + e.message + ')'; }
if (/^WITHDRAWN/.test(cardProbe)) toolsLog = '[' + cardProbe + '] ' + toolsLog;   // v238
return [{ json: { output: text.length ? text : fallback, claimProbe: claimProbe, cardProbe, memoryNote, toolsLog } }];

// Get Booker (main v175): who is asking, now from the reference cache instead of a live Airtable read (Tara,
// 29 Sep: staff changes are rare, so up to 15 minutes stale is accepted). Same result as the Airtable search
// {Slack User ID} = "<sender>": the matching Bookers records as {id, fields}, or one empty item when none match.
const user = String($('Slack Trigger').first().json.user || '').trim();
const s = $('Reference Snapshot').first().json;
const rows = (Array.isArray(s.bookers) ? s.bookers : [])
  .filter(r => user && String((r.fields || {})['Slack User ID'] || '').trim() === user);
const out = rows.map(r => ({ json: { id: r.id, fields: r.fields }, pairedItem: { item: 0 } }));
return out.length ? out : [{ json: {}, pairedItem: { item: 0 } }];

