const seriesKey = (ref, f) => 'prep-s' + pbHash(PB_SALT + '|series|' + String(ref || '').trim() + '|' + pbNorm(f.Title) + '|' + (f.Dates || []).map(pbNorm).join(';') + '|' + pbNorm(f.Time) + '|' + pbNorm(f.Room));
