    const ref = String((($('Slack Trigger').first() || {}).json || {}).user || '');
    let row = null; try { row = k ? $('Read Prepared').all().map(i => (i && i.json) || {}).find(r => r.cache_key === k && r.payload) : null; } catch (e) {}
