// Build Reply (main v271): every reply in the chat carries Book a room / My bookings (decided 15 Oct: every message leads to
// the buttons). An agent reply that still asks for booking details or asks for a yes is replaced by a pointer to the buttons.
const j = $input.first().json || {};
let text = String(j.output || '').trim();
let agent = false; try { agent = !!$('Guard Probe').first().json; } catch (e) { agent = false; }
const BOOKING_ASK = /(?:who(?:’|')?s the (?:client|engineer|arranger)|what(?:’|')?s the (?:project|client)|which (?:session type|room|studio)|what (?:kind|type) of (?:session|booking)|what time (?:should|works|do you)|confirm to (?:book|cancel|move)|reply yes or no|book it\?|\(yes\/no\))/i;
// v286 (28 Oct): drop only the sentences that ask for booking details - an answer before them stays ("what rooms have
// symphony?" lost its whole answer to a closing "Which room would you like?"); the pointer only when nothing is left
if (agent && BOOKING_ASK.test(text)) {
  // kept: statements only - no question ("Cancel it?"), no leftover aside ("(or none)"), no "Reply yes or no"
  const keep = s => !BOOKING_ASK.test(s) && !/\?\s*$/.test(s) && !/^\(.*\)$/.test(s.trim()) && !/\b(?:yes or no|yes\/no)\b/i.test(s);
  const kept = text.split('\n').map(l => l.split(/(?<=[.!?])\s+/).filter(keep).join(' ').trimEnd());
  const left = kept.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  const collecting = /\*?(?:project|client|engineer|arranger|session type|date|time|room|booked by|department):\*?\s/i.test(left) || /\b(?:noted|so far|got it|i(?:’|')?ll book|i can book|let me book|i(?:’|')?ve (?:added|put|set|noted))\b/i.test(left);
  text = (left.match(/[a-z0-9]+/gi) || []).length >= 3 && !collecting ? left : 'Use *Book a room* or *My bookings* below.';   // v275
}
if (!text) text = 'What would you like to do?';
const chunks = []; for (let i = 0; i < text.length && chunks.length < 40; i += 2900) chunks.push(text.slice(i, i + 2900));
// v272: Book a room opens the form at what THIS message named - its date, times and room (nothing from earlier messages)
let bookValue = 'menu';
try {
  const g = $('Gate Context').first().json || {}, bf = $('Booked For').first().json || {};
  const tx = String((($('Slack Trigger').first().json || {}).text) || '');
  const P = {};
  const ds = String(g.datesInMessage || '').split(',').map(x => x.trim()).filter(x => /^\d{4}-\d{2}-\d{2}$/.test(x));
  if (ds.length === 1) P.d = ds[0];
  if (bf.timeInNewest && /^\d{2}:\d{2}$/.test(String(bf.timeStart || '')) && /^\d{2}:\d{2}$/.test(String(bf.timeEnd || '')) && bf.timeStart < bf.timeEnd) { P.s = bf.timeStart; P.e = bf.timeEnd; }
  const rm = []; let m; const r1 = /\bstudio\s*([1-8a-fm])\b/gi; while ((m = r1.exec(tx))) rm.push('Studio ' + m[1].toUpperCase());
  const r2 = /\bm[\s-]?booth\s*([1-8])\b|\bm-?([1-8])\b/gi; while ((m = r2.exec(tx))) rm.push('M' + (m[1] || m[2]));
  for (const n of ['Likha', 'Salin', 'Katha', 'Lobby']) if (new RegExp('\\b' + n + '\\b', 'i').test(tx)) rm.push(n);
  if (rm.length === 1) P.r = rm[0];
  // v281: "the whole day" with no times - 12:00 AM to 11:59 PM (an M booth or the Lobby: the form's All day box instead)
  if (!P.s && /\b(?:all|whole|full|entire)[\s-]?day\b/i.test(tx) && !/\bhalf[\s-]?day\b/i.test(tx) && !/^(?:M[1-8]|Lobby)$/.test(String(P.r || ''))) { P.s = '00:00'; P.e = '23:59'; }
  if (Object.keys(P).length) bookValue = JSON.stringify(P);
} catch (e) { bookValue = 'menu'; }
const blocks = chunks.map(c => ({ type: 'section', text: { type: 'mrkdwn', text: c } })).concat([{ type: 'actions', elements: [
  { type: 'button', style: 'primary', action_id: 'open_book', value: bookValue, text: { type: 'plain_text', text: 'Book a room' } },
  { type: 'button', action_id: 'my_bookings', value: 'menu', text: { type: 'plain_text', text: 'My bookings' } } ] }]);
