// Mine Check (main v272, PENDING 100): "what do I have this week / tomorrow / on the 20th / in November", "my bookings", "my
// schedule" - answered in code with the My bookings list (Mine Reply), never written by the AI (live 16:47 it added
// "Filtering for …" and the engineer / arranger to every row). Works out the window; never throws.
const item = Object.assign({}, $input.first().json);
const mc = { go: false, why: '', timeMin: '', timeMax: '', start: '', end: '', week: false, channel: '', user: '' };
try {
  const g = $('Gate Context').first().json || {}, gate = g.gate || {};
  const trig = $('Slack Trigger').first().json || {};
  mc.channel = String(trig.channel || ''); mc.user = String(trig.user || '');
  const t = String(trig.text || '').replace(/\*sent using\*[\s\S]*$/i, '').toLowerCase().replace(/[’']/g, '');
  const mine = /\bwhat (?:do|have) i (?:got|have)\b|\bwhat do i have\b|\bwhats? (?:on )?my (?:schedule|calendar|bookings?|sessions?)\b|\bmy (?:bookings?|sessions?|schedule|calendar)\b|\bam i (?:booked|on|engineering|arranging)\b|\bdo i have (?:any )?(?:bookings?|sessions?)\b|\bwhere am i\b/.test(t)
    || /\bdo i have\b[^?.!]{0,40}?\b(?:bookings?|sessions?)\b|\bmy\b[^?.!]{0,25}?\b(?:bookings?|sessions?)\b/.test(t)   // v279 (QA 22 Oct): \"do i have studio 8 bookings\"
    || (/\bdid i (?:book|reserve)\b|\bwhat (?:did )?i (?:booked|book|reserved)\b|\bany(?:thing| bookings?| sessions?)\b(?: \w+){0,2}? for me\b|\bdo i have anything\b/.test(t)
        && !/\b(?:free|available|availability|open|vacant)\b/.test(t));   // v279: \"did i book studio 8\", \"what i booked\", \"anything for me\", \"do i have anything tomorrow\" - never \"anything free\"
  if (!mine) mc.why = 'not a my-bookings question';
  else if (/\b(?:cancel|delete|remove|move|resched\w*|change|push|extend|shorten|book)\b/.test(t.replace(/\b(?:did|what(?: did)?) i book\b/g, ''))) mc.why = 'a change / cancel / booking';
  else if (g.confirmed || g.confirmedCancel || g.confirmedMove || gate.presentedBook || gate.presentedCancel || gate.presentedMove) mc.why = 'answering a chat card';
  else {
    const today = /^\d{4}-\d{2}-\d{2}$/.test(String(g.todayIso || '')) ? g.todayIso : new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10);
    const add = (d, n) => new Date(Date.parse(d + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
    const ds = String(g.datesInMessage || '').split(',').map(x => x.trim()).filter(x => /^\d{4}-\d{2}-\d{2}$/.test(x)).sort();
    const MON = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
    const mm = t.match(/\b(?:in|for|during|this|next)?\s*(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\b(?!\s*\d)/);
    let start = today, end = add(today, 7), week = true;
    // v282 (26 Oct, "what are my bookings nov 1-4" listed Nov 1 only): a written span - "nov 1-4", "nov 1 to 4", "oct 30 - nov 2",
    // "1-4 nov" - is the window, first day to last (Gate Context passes only its first date)
    const _M = '(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\\.?', _D = '(\\d{1,2})(?:st|nd|rd|th)?', _TO = '\\s*(?:-|\u2013|\u2014|to|thru|through|until|till)\\s*';
    const _s1 = t.match(new RegExp('\\b' + _M + '\\s+' + _D + _TO + '(?:' + _M + '\\s+)?' + _D + '\\b(?!\\s*(?::|am\\b|pm\\b|nn\\b))'));
    const _s2 = !_s1 && t.match(new RegExp('\\b' + _D + _TO + _D + '\\s+(?:of\\s+)?' + _M + '\\b'));
    let _span = null;
    if (_s1 || _s2) {
      const MI = x => ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'].indexOf(String(x).slice(0, 3));
      const m1 = _s1 ? MI(_s1[1]) : MI(_s2[3]), d1 = +(_s1 ? _s1[2] : _s2[1]), m2 = _s1 ? (_s1[3] ? MI(_s1[3]) : m1) : m1, d2 = +(_s1 ? _s1[4] : _s2[2]);
      const y0 = +today.slice(0, 4), mo0 = +today.slice(5, 7) - 1, y1 = m1 < mo0 ? y0 + 1 : y0, y2 = m2 < m1 ? y1 + 1 : y1;
      const iso = (y, m, d) => { const x = new Date(Date.UTC(y, m, d)); return x.getUTCMonth() === m && x.getUTCDate() === d ? x.toISOString().slice(0, 10) : ''; };
      const a = iso(y1, m1, d1), b = iso(y2, m2, d2);
      if (a && b && b >= a && (Date.parse(b) - Date.parse(a)) / 86400000 <= 62) _span = [a, add(b, 1)];
    }
    if (_span) { start = _span[0]; end = _span[1]; week = false; }
    else if (/\bnext week\b/.test(t)) { start = add(today, 7); end = add(today, 14); }
    else if (/\bthis month\b/.test(t) || mm) {
      const y0 = +today.slice(0, 4), mo0 = +today.slice(5, 7) - 1;
      const mo = mm ? MON.findIndex(x => x.startsWith(mm[1].slice(0, 3))) : mo0;
      const y = mo < mo0 ? y0 + 1 : y0;
      start = y + '-' + String(mo + 1).padStart(2, '0') + '-01'; end = new Date(Date.UTC(y, mo + 1, 1)).toISOString().slice(0, 10);
      if (start < today && mo === mo0) start = today;
      week = false;
    }
    else if (ds.length === 1 && !/\b(?:this|next) week\b|\bweek\b/.test(t)) { start = ds[0]; end = add(ds[0], 1); week = false; }
    else if (ds.length > 1) { start = ds[0]; end = add(ds[ds.length - 1], 1); week = false; }
    // v279: a room named narrows the list ("do i have studio 8 bookings")
    const _rm = t.match(/\bstudio\s+([0-9]{1,2}|[a-z])\b|\b(m[1-8])\b|\b(likha|katha|salin|lobby)\b/);
    mc.room = !_rm ? '' : _rm[1] ? 'Studio ' + _rm[1].toUpperCase() : _rm[2] ? _rm[2].toUpperCase() : _rm[3].charAt(0).toUpperCase() + _rm[3].slice(1);
    Object.assign(mc, { go: !!mc.channel && !!mc.user, why: 'my bookings', start, end, week, timeMin: start + 'T00:00:00+08:00', timeMax: end + 'T00:00:00+08:00' });
  }
} catch (e) { mc.go = false; mc.why = 'error: ' + ((e && e.message) || e); }
item.mineCheck = mc;
return [{ json: item }];

// Booking rows - the same blocks Slack Interactions v11 renders (bk_<id> + bka_<id>), so its Change / Cancel handle them.
const _DS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'], _MS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function t12(hm) { if (!hm) return ''; let [h, m] = String(hm).split(':').map(Number); const ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12; return h + ':' + String(m).padStart(2, '0') + ' ' + ap; }
function dayShort(d) { const x = new Date(d + 'T12:00:00Z'); return _DS[x.getUTCDay()] + ', ' + _MS[x.getUTCMonth()] + ' ' + x.getUTCDate(); }
// v274: a booking's rooms - the studio (+ its booth), then the holding rooms; all day for 12:00 AM to 12:00 AM
function roomList(r) { return String(r || '').split(',').map(x => x.trim()).filter(Boolean); }
function roomMain(r) { const a = roomList(r); return [a[0]].concat(a.slice(1).filter(x => /^(?:Studio\s|M\d)/i.test(x))).filter(Boolean).join(' + '); }
function roomHold(r) { return roomList(r).slice(1).filter(x => !/^(?:Studio\s|M\d)/i.test(x)).join(', '); }
function whenLine(b) { return dayShort(b.d) + ' · ' + (b.s && !(b.s === '00:00' && b.e === '00:00') ? t12(b.s) + ' – ' + t12(b.e) : 'all day') + (b.r ? ' · ' + roomMain(b.r) + (roomHold(b.r) ? ' + ' + roomHold(b.r) : '') : ''); }
function mins(hm) { const m = String(hm || '').match(/^(\d{2}):(\d{2})$/); return m ? +m[1] * 60 + +m[2] : null; }
function hhmm(n) { return String(Math.floor(n / 60)).padStart(2, '0') + ':' + String(n % 60).padStart(2, '0'); }
// the new values: what was typed over the booking's own; a start alone keeps the length
function newOf(b, n) {
  n = n || {}; const o = { d: n.d || b.d, s: b.s, e: b.e, r: n.r || b.r };
  if (n.s && n.e) { o.s = n.s; o.e = n.e; }
  else if (n.s && mins(b.s) !== null && mins(b.e) !== null) { const e = mins(n.s) + (mins(b.e) - mins(b.s)); o.s = n.s; o.e = e < 1440 ? hhmm(e) : ''; }
  else if (n.e) o.e = n.e;
  return o;
}
function bkValue(b, n) { const v = { id: b.id, d: b.d, s: b.s || '', e: b.e || '', r: b.r || '', t: String(b.t || '').slice(0, 150), st: b.st || '' };   // v274: st
  if (n && Object.keys(n).length) v.n = n; return JSON.stringify(v); }
function bkButtons(b, n) {
  const pt = x => ({ type: 'plain_text', text: x });
  return { type: 'actions', block_id: 'bka_' + b.id, elements: [
    { type: 'button', action_id: 'bk_change', value: bkValue(b, n), text: pt('Change') },
    { type: 'button', action_id: 'bk_cancel', style: 'danger', value: bkValue(b), text: pt('Cancel'),
      confirm: { title: pt('Cancel this booking?'), text: { type: 'mrkdwn', text: ('*' + b.t + '*\n' + whenLine(b)).slice(0, 290) },
                 confirm: pt('Cancel booking'), deny: pt('Keep it'), style: 'danger' } } ] };
}
// v270: a calendar room label ("KDC Plaza-Top Level-Likha (Big Room)") -> the room's own name ("Likha")
function roomName(x) { return String(x || '').replace(/^KDC Plaza-Top Level-/i, '').replace(/(?:\s*\([^)]*\))+\s*$/, '').trim(); }   // v274: every "(…)" 
function evRoom(e) { const r = (e.attendees || []).filter(a => a.resource || /@resource\.calendar\.google\.com$/i.test(String(a.email || '')))
  .map(a => roomName(a.displayName)).filter(Boolean);
  // v274: Google lists the rooms in its own order - the booking's "Rooms:" line keeps studio, booth, holding rooms
  const w = (String(e.description || '').match(/(?:^|\|)\s*Rooms:\s*([^|\n]+)/i) || [])[1];
  if (w && r.length) { const o = w.split(',').map(x => x.trim()).filter(Boolean), lc = a => a.map(x => x.toLowerCase()).sort().join();
    if (lc(o) === lc(r)) return r.slice().sort((x, y) => o.findIndex(z => z.toLowerCase() === x.toLowerCase()) - o.findIndex(z => z.toLowerCase() === y.toLowerCase())).join(', '); }
  return r.length ? r.join(', ') : roomName(e.location); }
function evType(e) { return ((String(e.description || '').match(/\n\s*SType:\s*([^\n]+)/) || [])[1] || '').trim(); }   // v274
// v44 / v283 / Reminders v6 (26 Oct, Howard): the booking's note in Slack - "*Notes:*" at the end of a card, "📝" and its first
// line in a list. From the event's "Notes:" block (Book Session v122) or an older booking's inline "| Notes: …".
function evNote(e) { const d = String((e && e.description) || ''); const m = d.match(/\n\s*\n\s*Notes?:\s*([\s\S]*)$/i) || d.match(/(?:^|\|)\s*Notes?:\s*([^|]*)$/i) || d.match(/(?:^|\|)\s*Notes?:\s*([^|\n]*)/i); return m ? m[1].trim() : ''; }
function noteLine(nt) { nt = String(nt || '').trim(); if (!nt) return ''; if (nt.length > 600) nt = nt.slice(0, 600).trim() + '…'; return '\n*Notes:*' + (/\n/.test(nt) ? '\n' : ' ') + nt; }
function noteRow(nt) { const f = String(nt || '').split('\n').map(x => x.trim()).find(Boolean) || ''; return f ? '\n📝 ' + (f.length > 80 ? f.slice(0, 80).trim() + '…' : f) : ''; }
function evBooking(e) {
  const sd = e.start && e.start.dateTime, ed = e.end && e.end.dateTime;
  const m = x => { const d = new Date(new Date(x).getTime() + 8 * 3600000); return { d: d.toISOString().slice(0, 10), hm: d.toISOString().slice(11, 16) }; };
  if (sd) { const a = m(sd), b = m(ed); return { id: e.id, d: a.d, s: a.hm, e: b.hm, r: evRoom(e), t: e.summary || '(no title)', st: evType(e), nt: evNote(e) }; }
  return { id: e.id, d: String((e.start && e.start.date) || ''), s: '', e: '', r: evRoom(e), t: e.summary || '(no title)', st: evType(e), nt: evNote(e) };
}

// Mine Reply (main v272): the person's bookings in the window - made, or engineered / arranged - as My bookings shows them:
// title, date, time, room, each with Change / Cancel; Previous / Next 7 days for a week.
const mc = ($('Mine Check').first().json || {}).mineCheck || {};
const res = $input.first().json || {};
const md = t => ({ type: 'mrkdwn', text: t });
const addD = (d, n) => new Date(Date.parse(d + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const head = mc.end === addD(mc.start, 1) ? dayShort(mc.start) : dayShort(mc.start) + ' – ' + dayShort(addD(mc.end, -1));
const blocks = [{ type: 'section', text: md('*Your bookings' + (mc.room ? ' in ' + mc.room : '') + '* · ' + head) }];   // v279: a room asked about
const items = Array.isArray(res.items) ? res.items : null;
let count = 0;
if (!items) blocks.push({ type: 'section', text: md('⚠️ The calendar couldn’t be read. Try again in a moment.') });
else {
  const rows = [];
  for (const e of items) {
    if (!e || e.status === 'cancelled') continue;
    const desc = String(e.description || '').split(/\n|<br\s*\/?>/i)[0].replace(/(?:^|\|)\s*Notes?:.*$/i, '');   // v46 / Move v39 / Cancel v33 / Reminders v7 / main v284 (PENDING 127): the first line only - never the note
    const ref = (desc.match(/ref:\s*([A-Za-z0-9]+)/) || [])[1] || '';
    const team = ((desc.match(/team:\s*([^|]+)/) || [])[1] || '').split(/[\s,]+/).filter(Boolean);
    if (ref !== mc.user && team.indexOf(mc.user) === -1) continue;
    const _b = evBooking(e);
    if (mc.room && !String(_b.r || '').split(',').some(x => x.trim().toLowerCase() === mc.room.toLowerCase())) continue;   // v279
    rows.push(_b);
  }
  rows.sort((a, b) => (a.d + (a.s || '00:00')).localeCompare(b.d + (b.s || '00:00')));
  count = rows.length;
  if (!rows.length) blocks.push({ type: 'section', text: md('Nothing booked for you' + (mc.room ? ' in ' + mc.room : '') + ' then.') });   // v279
  for (const b of rows.slice(0, 20)) blocks.push({ type: 'section', block_id: 'bk_' + b.id, text: md('*' + b.t + '*\n' + whenLine(b) + noteRow(b.nt)) }, bkButtons(b));
  if (rows.length > 20) blocks.push({ type: 'context', elements: [md('Showing the first 20 of ' + rows.length + '.')] });
}
if (mc.week) blocks.push({ type: 'actions', block_id: 'my_nav', elements: [
  { type: 'button', action_id: 'my_page_prev', value: addD(mc.start, -7), text: { type: 'plain_text', text: '← Previous 7 days' } },
  { type: 'button', action_id: 'my_page_next', value: addD(mc.start, 7), text: { type: 'plain_text', text: 'Next 7 days →' } } ] });
blocks.push({ type: 'actions', block_id: 'menu_nav', elements: [
  { type: 'button', style: 'primary', action_id: 'open_book', value: 'menu', text: { type: 'plain_text', text: 'Book a room' } } ] });
return [{ json: { channel: mc.channel, text: 'Your bookings · ' + head, blocks, count } }];

// Facts Check (main v286, Howard 28 Oct: "what rooms have symphony?" got only "Use Book a room or My bookings below."):
// questions about what the rooms have - equipment, setup, workstation, capacity, pairing - answered in code from the rooms in
// the reference cache (every Rooms & Studios field; no Airtable call). Two shapes:
// - "which rooms have <thing>" -> every room whose details name it, with the line that says so ("no Mac Studio" is not a match);
// - a setup question about one named room ("what's in Studio F", "does Studio 8 have a Mac Studio?") -> that room's details.
// Availability, bookings, formats across rooms and session types go on to the AI and its tools. Never throws: on any doubt, the AI.
const item = Object.assign({}, $input.first().json);
const fc = { go: false, why: '', shape: '', term: '', rooms: [], channel: '', text: '', blocks: [] };
const arrOf = v => [].concat(v == null ? [] : v).map(x => (x && typeof x === 'object') ? String(x.name || '') : String(x)).map(s => s.trim()).filter(Boolean);
const plainOf = s => String(s == null ? '' : s).replace(/\*+/g, '').replace(/[ \t]+/g, ' ').trim();
const capOf = s => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
// one room's Airtable details as {label, text} - Room Type, Size + Capacity, Recording Format, Workstation, the vocal flags,
// Paired with, Prioritized For, Equipment (one per sentence) and Equipment (additional) under its own headings
function factsOf(f) {
  const out = [];
  const type = arrOf(f['Room Type']); if (type.length) out.push({ label: 'Room type', text: type.join(', ') });
  const size = plainOf(f['Size Category']), cp = Number(f['Capacity']);
  const people = Number.isFinite(cp) && cp > 0 ? 'up to ' + cp + (cp === 1 ? ' person' : ' people') : '';
  if (size || people) out.push({ label: 'Size', text: [size, people].filter(Boolean).join(' · ') });
  const fm = arrOf(f['Recording Format']).filter(x => !/^none$/i.test(x)); if (fm.length) out.push({ label: 'Formats', text: fm.join(', ') });
  const ws = arrOf(f['Workstation']); if (ws.length) out.push({ label: 'Workstation', text: ws.join(', ') });
  if (f['Vocal Booth'] === true) out.push({ label: 'Vocal booth', text: 'yes' });
  if (f['Records Vocals In-Room'] === true) out.push({ label: 'Vocals', text: 'recorded in the room' });
  const pw = plainOf(f['Paired with']); if (pw && !/^n\/?a$/i.test(pw)) out.push({ label: 'Paired with', text: pw });
  const pf = arrOf(f['Prioritized For']); if (pf.length) out.push({ label: 'Prioritized for', text: pf.join(', ') });
  for (const s of String(f['Equipment'] || '').split(/\n+|(?<=\.)\s+/)) { const x = plainOf(s).replace(/\.$/, ''); if (x) out.push({ label: 'Equipment', text: x }); }
  let head = 'Equipment';
  for (const ln of String(f['Equipment (additional)'] || '').split(/\n/)) {
    const h = ln.match(/^\s*\*\*\s*(.+?)\s*\*\*\s*$/); if (h) { head = capOf(h[1].trim()); continue; }
    const x = plainOf(ln.replace(/^\s*[-•*]\s*/, '')); if (x) out.push({ label: head, text: x });
  }
  return out;
}
// the facts grouped by label, in order: [[label, [texts]]]
function groupsOf(facts) {
  const g = [], at = {};
  for (const x of facts) { if (!(x.label in at)) { at[x.label] = g.length; g.push([x.label, []]); } g[at[x.label]][1].push(x.text); }
  return g;
}

try {
  const g = $('Gate Context').first().json || {};
  const trig = $('Slack Trigger').first().json || {};
  fc.channel = String(trig.channel || '');
  const raw = String(trig.text || '').slice(0, 500).replace(/\*sent using\*[\s\S]*$/i, '').replace(/<[^>]+>/g, ' ');
  const t = raw.toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9.+&!\s\/-]/g, ' ').replace(/\s+/g, ' ').replace(/[.!]+$/, '').trim();
  const rooms = [];
  for (const it of $('All Rooms').all()) { const f = ((it && it.json) || {}).fields || {}; const nm = String(f['Room Name'] || '').trim(); if (nm) rooms.push({ name: nm, facts: factsOf(f) }); }
  const types = [];
  try { for (const it of $('All Session Types').all()) { const ty = String((((it && it.json) || {}).fields || {})['Type'] || '').trim().toLowerCase(); if (ty) types.push(ty); } } catch (e) {}
  const asks = /\?/.test(raw) || /^(?:what|whats|which|where|wheres|does|do|is|are|any|list|show|tell|how|can|got)\b/.test(t) || /\brooms? with\b/.test(t);
  const when = !!String(g.datesInMessage || '').trim()
    || /\b(?:free|available|availability|vacant|open|booked|book|booking|reserve|schedule|calendar|today|tomorrow|tonight|now|later|week|month|monday|tuesday|wednesday|thursday|friday|saturday|sunday|mon|tue|wed|thu|fri|sat|sun|noon|cancel|move|change|taken|busy|occupied|reserved|left|sessions?|bookings?|meetings?|slots?|someone|anyone|anybody|who|whos|client|engineer|arranger|project)\b/.test(t)
    || /\b(?:at|from|until|till|by|on|before|after)\s+\d/.test(t)
    || /\b\d{1,2}(?::\d{2})?\s*(?:am|pm|nn)\b/.test(t) || /\bmy\b/.test(t);
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const FORMAT = /^(?:5\.1|7\.1|atmos|dolby(?: atmos)?|stereo(?: with sub)?|surround|mono)(?: (?:mixing|format|sound))?$/;
  const tidy = s => String(s || '').replace(/^(?:an?|the|any|some|a pair of)\s+/, '').replace(/\s+(?:setups?|set ups?|installed|in (?:it|them|there)|inside|please|pls|po|naman)$/g, '').trim();
  // a term as a regex: the words in order, the last one with or without its plural
  const termRe = term => {
    const w = term.split(/\s+/).filter(Boolean).map(esc); if (!w.length) return null;
    const last = w.pop(), sing = /[a-z]{3,}(?:es|s)$/.test(last) ? last.replace(/(?:es|s)$/, '') : last;
    return new RegExp('(^|[^a-z0-9])(' + w.concat(['(?:' + last + '|' + sing + '(?:es|s)?)']).join('[\\s-]*') + ')(?![a-z0-9])', 'i');
  };
  // the facts of one room that name the term - not after "no" / "without" / "not"
  const hitsIn = (room, re, labels) => room.facts.filter(x => {
    if (labels && labels.indexOf(x.label) === -1) return false;
    const m = re.exec(x.text); if (!m) return false;
    return !/\b(?:no|without|not)\s+(?:an?\s+)?$/i.test(x.text.slice(0, m.index + m[1].length));
  });
  // v286: Slack's three escapes on everything printed - Airtable text and the typed term never become a mention or a link
  const se = v => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const line = x => se((x.label === 'Equipment' ? '' : x.label + ': ') + x.text);
  const nat = (a, b) => a.localeCompare(b, undefined, { numeric: true });
  // rooms named in the message
  const named = rooms.filter(r => {
    const n = r.name.toLowerCase();
    let re;
    const st = n.match(/^studio\s+(\S+)$/), mb = n.match(/^m(\d)$/);
    if (st) re = new RegExp('\\bstudio\\s*' + esc(st[1]) + '\\b(?!\\s*(?:studio|mini))');
    else if (mb) re = new RegExp('\\bm[\\s-]?(?:booth\\s*)?' + mb[1] + '\\b');
    else re = new RegExp('\\b' + esc(n) + '\\b');
    return re.test(t);
  });
  const isType = term => types.some(ty => term === ty || term.indexOf(ty) !== -1 || (term.length > 4 && ty.indexOf(term) !== -1));
  if (!asks) fc.why = 'not a question';
  else if (when) fc.why = 'about a time or a booking';
  else if (!rooms.length) fc.why = 'no rooms in the cache';
  if (!fc.why) {
    // shape 1: which rooms have <thing>
    const m1 = t.match(/^(?:(?:which|what|wat|any|list(?: the| all)?|show(?: me)?(?: the| all)?)\s+)?(?:of the\s+)?(?:rooms?|studios?|booths?)\s+(?:(?:that|which)\s+)?(?:have|has|got|use|uses|come with|comes with|are equipped with|is equipped with|equipped with|with|carry|carries)\s+(.+)$/)
      || t.match(/^(?:does|do)\s+any\s+(?:rooms?|studios?|booths?)\s+(?:have|has|use|come with)\s+(.+)$/)
      || t.match(/^(?:is|are)\s+there\s+(?:an?\s+|any\s+)?(?:rooms?|studios?|booths?)\s+with\s+(.+)$/)
      || t.match(/^where\s+(?:is|are|can i (?:find|use))\s+(.+)$/)
      || t.match(/^(?:which|what)\s+(?:rooms?|studios?|booths?)\s+(?:is|are)\s+(.+)$/);
    if (m1 && !named.length) {
      const term = tidy(m1[1]);
      fc.term = term;
      if (!term || term.split(' ').length > 4 || /\d|\b(?:people|pax|persons?|space|seats?|capacity|most|best|biggest|smallest|more|less)\b/.test(term)) fc.why = 'no clear thing to look for';
      else if (FORMAT.test(term)) fc.why = 'a format (Rooms and Studios answers it)';
      else if (isType(term) || /\b(?:vocal|booths?|session|sessions)\b/.test(term)) fc.why = 'a session type or a booth (the AI answers it)';
      else {
        const re = termRe(term);
        const found = [];
        for (const r of rooms) { const h = hitsIn(r, re); if (h.length) found.push({ r, h }); }
        found.sort((a, b) => nat(a.r.name, b.r.name));
        if (!found.length) fc.why = 'no room lists it (the AI answers, from the details)';
        else {
          fc.shape = 'which rooms'; fc.go = true;
          const m = re.exec(found[0].h[0].text); const shown = m ? m[2] : term;
          fc.rooms = found.map(x => x.r.name);
          fc.text = '*Rooms with ' + se(shown) + ':*\n' + found.slice(0, 30).map(x => '• *' + se(x.r.name) + '* – ' + x.h.slice(0, 2).map(line).join(' · ')).join('\n');
        }
      }
    } else if (named.length === 1) {
      // shape 2: one room's setup
      const r = named[0], nm = r.name.toLowerCase().replace(/^studio\s+/, 'studio\\s*');
      const gear = /\b(?:equipment|gear|setup|set up|specs?|specifications|features|inside|interfaces?|preamps?|speakers?|monitors?|mics?|microphones?|console|workstation|computer|mac|laptop|capacity|fit|size|big|paired|pair|details?|tell me about|have|has|got|in it|whats inside|what is inside)\b/.test(t);
      if (!gear) fc.why = 'a room named, but not its setup';
      else {
        const m2 = t.match(new RegExp('^(?:does|do|is there|has)\\s+(?:the\\s+)?' + nm + '\\s+(?:have|has|got|come with|use)\\s+(.+)$'))
          || t.match(new RegExp('^(?:is|are)\\s+there\\s+(.+?)\\s+in\\s+(?:the\\s+)?' + nm + '$'))
          || t.match(new RegExp('^(?:the\\s+)?' + nm + '\\s+(?:has|have|got)\\s+(.+)$'));
        const term = m2 ? tidy(m2[1]) : '';
        const out = [];
        if (term && term.split(' ').length <= 4 && !/^(?:it|anything|what)$/.test(term)) {
          fc.term = term;
          const h = hitsIn(r, termRe(term), FORMAT.test(term) ? ['Formats'] : null);
          if (h.length) out.push('*' + se(r.name) + '* has ' + se(term) + ':\n' + h.slice(0, 4).map(x => '• ' + line(x)).join('\n'));
          else out.push('Airtable doesn’t list *' + se(term) + '* for *' + se(r.name) + '*.');
          out.push('');
        }
        out.push('*' + se(r.name) + '*');
        for (const [label, texts] of groupsOf(r.facts)) out.push('*' + se(label) + ':* ' + se(texts.join(label === 'Equipment' ? '. ' : ', ')));
        if (r.facts.length === 0) out.push('Airtable lists no details for this room yet.');
        fc.shape = 'one room'; fc.go = true; fc.rooms = [r.name];
        fc.text = out.join('\n');
      }
    } else fc.why = named.length > 1 ? 'more than one room named' : 'not a question about what rooms have';
  }
  if (fc.go) {
    fc.text = fc.text.slice(0, 2900);
    fc.blocks = [{ type: 'section', text: { type: 'mrkdwn', text: fc.text } }, { type: 'actions', elements: [
      { type: 'button', style: 'primary', action_id: 'open_book', value: 'menu', text: { type: 'plain_text', text: 'Book a room' } },
      { type: 'button', action_id: 'my_bookings', value: 'menu', text: { type: 'plain_text', text: 'My bookings' } } ] }];
  }
} catch (e) { fc.go = false; fc.why = 'error: ' + e.message; }
return [{ json: Object.assign(item, { factsCheck: fc }) }];
